    return a < 0 ? negate(a) : a;
  }

  public Operations() {}

  public int minus(int a, int b) {
    return a + negate(b);
  }

  public int multiply(int a, int b) {
    int res = 0;
    int x = absVal(a), y = absVal(b);
    while (y > 0) {
      if ((y & 1) == 1) res += x;
      x <<= 1;
      y >>= 1;
    }
    if ((a < 0) != (b < 0)) res = negate(res);
    return res;
  }

  public int divide(int a, int b) {
    if (b == 0) return 0;
    long x = absVal(a), y = absVal(b), q = 0;
    while (x >= y) {
      x -= y;
      q++;
    }
    int res = (int) q;
    if ((a < 0) != (b < 0)) res = negate(res);
    return res;
  }
}

class Operations:
    def _negate(self, a: int) -> int:
        return ~a + 1

    def _abs(self, a: int) -> int:
        return self._negate(a) if a < 0 else a

    def minus(self, a: int, b: int) -> int:
        return a + self._negate(b)

    def multiply(self, a: int, b: int) -> int:
        res = 0
        x, y = self._abs(a), self._abs(b)
        while y > 0:
            if y & 1:
                res += x
            x <<= 1
            y >>= 1
        if (a < 0) != (b < 0):
            res = self._negate(res)
        return res

    def divide(self, a: int, b: int) -> int:
        if b == 0:
            return 0
        x, y, q = self._abs(a), self._abs(b), 0
        while x >= y:
            x -= y
            q += 1
        if (a < 0) != (b < 0):
            q = self._negate(q)
        return q

impl Operations {
  pub fn new() -> Self {
    Operations {}
  }

  fn negate(a: i32) -> i32 {
    !a + 1
  }

  fn abs_val(a: i32) -> i32 {
    if a < 0 {
      Self::negate(a)
    } else {
      a
    }
  }

  pub fn minus(&self, a: i32, b: i32) -> i32 {
    a + Self::negate(b)
  }

  pub fn multiply(&self, a: i32, b: i32) -> i32 {
    let mut res = 0;
    let (mut x, mut y) = (Self::abs_val(a), Self::abs_val(b));
    while y > 0 {
      if y & 1 == 1 {
        res += x;
      }
      x <<= 1;
      y >>= 1;
    }
    if (a < 0) != (b < 0) {
      res = Self::negate(res);
    }
    res
  }

  pub fn divide(&self, a: i32, b: i32) -> i32 {
    if b == 0 {
      return 0;
    }
    let (mut x, y): (i64, i64) = (Self::abs_val(a) as i64, Self::abs_val(b) as i64);
    let mut q: i64 = 0;
    while x >= y {
      x -= y;
      q += 1;
    }
    let mut res = q as i32;
    if (a < 0) != (b < 0) {
      res = Self::negate(res);
    }
    res
  }
}

class Operations {
  private negate(a: number): number {
    return ~a + 1;
  }

  private absVal(a: number): number {
    return a < 0 ? this.negate(a) : a;
  }

  minus(a: number, b: number): number {
    return a + this.negate(b);
  }

  multiply(a: number, b: number): number {
    let res = 0;
    let x = this.absVal(a);
    let y = this.absVal(b);
    while (y > 0) {
      if (y & 1) res += x;
      x <<= 1;
      y >>= 1;
    }
    if (a < 0 !== b < 0) res = this.negate(res);
    return res;
  }

  divide(a: number, b: number): number {
    if (b === 0) return 0;
    let x = this.absVal(a);
    const y = this.absVal(b);
    let q = 0;
    while (x >= y) {
      x -= y;
      q++;
    }
    if (a < 0 !== b < 0) q = this.negate(q);
    return q;
  }
}
